//! Renders and parses `circuits/lib/src/policy_tag.nr`, the generated Noir file
//! carrying `POLICY_SOURCE_HASH` and `STATE_TAG` as decimal `Field` literals.

use ark_bn254::Fr;
use ark_ff::{
    BigInteger,
    PrimeField,
};
use num_bigint::BigUint;

fn fr_to_decimal(fr: Fr) -> BigUint {
    BigUint::from_bytes_be(&fr.into_bigint().to_bytes_be())
}

/// The exact contents `cargo run --bin policy-tag` writes.
pub fn render(source_hash: Fr, tag: Fr) -> String {
    format!(
        "// Generated by `cargo run --bin policy-tag`. Do not edit.\n\
// Every gated circuit asserts STATE_TAG against a live Poseidon1 image, so a\n\
// stale literal here fails at proving time rather than silently.\n\
pub global POLICY_SOURCE_HASH: Field = {};\n\
pub global STATE_TAG: Field = {};\n",
        fr_to_decimal(source_hash),
        fr_to_decimal(tag),
    )
}

/// Extracts `POLICY_SOURCE_HASH` and `STATE_TAG` from a `policy_tag.nr`'s contents.
/// Compares the decimal values, not the surrounding bytes: `nargo fmt` reflows a long
/// literal onto its own line, so a byte-for-byte comparison against [`render`]'s output
/// fails even when the values agree.
pub fn parse(contents: &str) -> Option<(Fr, Fr)> {
    let source_hash =
        extract_decimal(contents, "pub global POLICY_SOURCE_HASH: Field =")?;
    let tag = extract_decimal(contents, "pub global STATE_TAG: Field =")?;
    Some((Fr::from(source_hash), Fr::from(tag)))
}

fn extract_decimal(contents: &str, marker: &str) -> Option<BigUint> {
    let start = contents.find(marker)?;
    let rest = &contents[start + marker.len()..];
    let digits_start = rest.find(|c: char| c.is_ascii_digit())?;
    let digits: String = rest[digits_start..]
        .chars()
        .take_while(char::is_ascii_digit)
        .collect();
    if digits.is_empty() {
        None
    } else {
        digits.parse::<BigUint>().ok()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn render_then_parse_round_trips() {
        let source_hash = Fr::from(7u64);
        let tag = Fr::from(42u64);
        let contents = render(source_hash, tag);
        let (parsed_source_hash, parsed_tag) =
            parse(&contents).expect("well-formed output");
        assert_eq!(parsed_source_hash, source_hash);
        assert_eq!(parsed_tag, tag);
    }

    #[test]
    fn parse_tolerates_a_reflowed_value_on_its_own_line() {
        let contents = "pub global POLICY_SOURCE_HASH: Field =\n    7;\npub global STATE_TAG: Field =\n    42;\n";
        let (source_hash, tag) = parse(contents).expect("reflowed output still parses");
        assert_eq!(source_hash, Fr::from(7u64));
        assert_eq!(tag, Fr::from(42u64));
    }

    #[test]
    fn parse_rejects_a_file_missing_a_declaration() {
        assert!(parse("pub global STATE_TAG: Field = 42;\n").is_none());
    }
}
